{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change 4: EF 9 uses patch (partial update) by default for Cosmos.
        // Sync-all-properties semantics now requires explicit full-document replace mode.
        context.SaveChanges();
    }

    // Breaking change 5: Raw SQL queries referencing "Discriminator" must be updated
    // only if you did NOT apply the HasDiscriminator("Discriminator") fix above.
    // With the fix, existing queries like:
    //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // continue to work unchanged. Without the fix, you'd need:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
}

